  (uuid_generate_v4(), 'squash-blossom-necklace-navajo-style-western-statement-necklace', '4453324176', 'https://www.etsy.com/listing/4453324176/squash-blossom-necklace-navajo-style?click_key=7734c4c2-8642-4296-ad51-b4d40acfa262%3ALTfb764f4015c71f100959841d9741230c6e2b25a7&click_sum=001265cc&ls=s&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-788646-19-25&sr_prefetch=1&pf_from=search&pro=1&frs=1&sts=1&content_source=7734c4c2-8642-4296-ad51-b4d40acfa262%253ALTfb764f4015c71f100959841d9741230c6e2b25a7',
