  (uuid_generate_v4(), '18-navajo-pearl-style-turquoise-pendant-necklace-blue-western-pearl-necklace-sto', '1866741549', 'https://www.etsy.com/listing/1866741549/18-navajo-pearl-style-turquoise-pendant?click_key=Eu0aUn4PzowjFtpPTpRLA0MDQ084%3ALT79650bf2ec8486a212505e7ae1e9f3794c37a941&click_sum=66998fb5&ls=a&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-788645-19-10&sr_prefetch=1&pf_from=search&pro=1&cns=1&sts=1',
