  (uuid_generate_v4(), 'navajo-pearl-necklace-gorgeous-southwest-colors-w-naja-pendant', '4318677540', 'https://www.etsy.com/listing/4318677540/navajo-pearl-handmade-three-strand?click_key=7734c4c2-8642-4296-ad51-b4d40acfa262%3ALT29233287201dbb80e05de013fb98d57084155a79&click_sum=eebbeed1&ls=s&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-788646-19-16&sr_prefetch=1&pf_from=search&frs=1&sts=1&content_source=7734c4c2-8642-4296-ad51-b4d40acfa262%253ALT29233287201dbb80e05de013fb98d57084155a79',
